-- ADCT, comentários didáticos, lote 10 (arts. 88 a 96, inclusive 92-A e 92-B; o 91 é revogado), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Alíquota mínima do ISS até a lei complementar$c$, aplicacao_pratica = $a$Enquanto a lei complementar não disciplinar o art. 156, § 3º, I e III, da Constituição, o imposto do art. 156, III (ISS), tem alíquota mínima de dois por cento, salvo para os serviços dos itens 32, 33 e 34 da lista anexa ao Decreto-Lei nº 406/1968 (I), e não pode ser objeto de isenções, incentivos e benefícios fiscais que resultem, direta ou indiretamente, em redução dessa alíquota mínima (II).$a$ where codigo='adct' and numero=88 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Quadro em extinção de servidores do ex-Território de Rondônia$c$, aplicacao_pratica = $a$Permite que integrantes da carreira policial militar e servidores municipais do ex-Território Federal de Rondônia em exercício regular na data da transformação em Estado, os alcançados pelo art. 36 da Lei Complementar nº 41/1981 e os admitidos regularmente pelo Estado até a posse do primeiro Governador eleito, em 15 de março de 1987, integrem, mediante opção, quadro em extinção da administração federal, com seus direitos e vantagens, vedado o pagamento de diferenças remuneratórias. O § 1º mantém os policiais militares cedidos ao Estado, submetidos às corporações, e o § 2º mantém os servidores cedidos até seu aproveitamento na administração federal direta, autárquica ou fundacional.$a$ where codigo='adct' and numero=89 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Prorrogação da contribuição sobre movimentação financeira até 2007$c$, aplicacao_pratica = $a$Prorrogou até 31 de dezembro de 2007 o prazo do art. 84 do ADCT para a cobrança da contribuição provisória sobre movimentação financeira. O § 1º prorrogou até essa data a vigência da Lei nº 9.311/1996 e o § 2º manteve a alíquota em 0,38% no período. Norma temporária de prazo já encerrado.$a$ where codigo='adct' and numero=90 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Prorrogação da Zona Franca de Manaus por dez anos$c$, aplicacao_pratica = $a$Acrescenta dez anos ao prazo fixado no art. 40 do ADCT para a Zona Franca de Manaus.$a$ where codigo='adct' and numero=92 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Prorrogação da Zona Franca de Manaus por cinquenta anos$c$, aplicacao_pratica = $a$Acrescenta cinquenta anos ao prazo fixado pelo art. 92 do ADCT, que já havia ampliado o prazo do art. 40 para a Zona Franca de Manaus.$a$ where codigo='adct' and numero=92 and titulo='Art. 92-A' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Diferencial competitivo da Zona Franca de Manaus na reforma tributária$c$, aplicacao_pratica = $a$Obriga as leis instituidoras dos tributos dos arts. 156-A e 195, V, da Constituição a prever mecanismos, com ou sem contrapartidas, para manter o diferencial competitivo da Zona Franca de Manaus (arts. 40 e 92-A do ADCT) e das áreas de livre comércio existentes em 31 de maio de 2023, nos níveis da legislação dos tributos extintos (arts. 126 a 129 do ADCT). O § 1º admite instrumentos fiscais, econômicos ou financeiros, os §§ 2º e 3º preveem lei complementar que institua o Fundo de Sustentabilidade e Diversificação Econômica do Estado do Amazonas, com aporte mínimo anual e possível compensação de perda de receita, o § 4º permite à União, por acordo com o Estado e com antecedência mínima de três anos, reduzir os instrumentos mediante aporte adicional ao Fundo, o § 5º afasta o art. 149-B, III e IV, e os §§ 6º e 7º preveem o Fundo de Desenvolvimento Sustentável dos Estados da Amazônia Ocidental e do Amapá.$a$ where codigo='adct' and numero=92 and titulo='Art. 92-B' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Início de vigência do art. 159, III, e § 4º$c$, aplicacao_pratica = $a$Condiciona a vigência do art. 159, III, e § 4º, da Constituição à edição da lei prevista naquele inciso III.$a$ where codigo='adct' and numero=93 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Fim dos regimes próprios para microempresas$c$, aplicacao_pratica = $a$Determina que cessem os regimes especiais de tributação para microempresas e empresas de pequeno porte próprios da União, dos Estados, do Distrito Federal e dos Municípios a partir da entrada em vigor do regime do art. 146, III, d, da Constituição.$a$ where codigo='adct' and numero=94 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Registro de nascidos no estrangeiro entre 1994 e a Emenda$c$, aplicacao_pratica = $a$Permite que os nascidos no estrangeiro entre 7 de junho de 1994 e a promulgação da Emenda, filhos de pai brasileiro ou mãe brasileira, sejam registrados em repartição diplomática ou consular brasileira competente ou em ofício de registro, se vierem a residir no Brasil.$a$ where codigo='adct' and numero=95 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Convalidação da criação de Municípios até 2006$c$, aplicacao_pratica = $a$Convalida os atos de criação, fusão, incorporação e desmembramento de Municípios cuja lei tenha sido publicada até 31 de dezembro de 2006, desde que atendidos os requisitos da legislação do respectivo Estado à época da criação.$a$ where codigo='adct' and numero=96 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
